{
  "gate_token": "5calHKpehw_xzrrRhG-D7A",
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unfolds a map of the ruined royal city.",
      "visual_description": "A windswept hill at dusk overlooking a shattered skyline of broken spires and torn banners; an ink-stained coat flaps as a brass compass spins.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of false paths ahead.",
      "visual_description": "A small oil lamp held up in gloved hands, its single flame-eye casting long shapes of ruined towers onto the map below.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
руль    {
      "scene_number": 3,
      "caption": "Tin Fox scouts the cracked outer gates.",
      "visual_description": "A small clockwork fox with blue glass eyes creeping along a tilted cobblestone road toward enormous iron gates hung with frayed royal banners.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "Glass Diver arrives by stepping out of a puddle.",
      "visual_description": "A figure in a clear diving helmet emerges from a rain puddle that ripples like a doorway, coat catching shattered reflections of broken city lights.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "The team plans their route past the cursed tower.",
      "visual_description": "Four companions huddle in a collapsed archway; the lamp's eye lights a scrap of map while a leaning black tower smokes in the background.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "They discover the sleeping tax collector slumped at his post.",
      "visual_description": "A snoring official sprawled across a toll booth, stamped papers stuck to his sleeves and a ledger book under his cheek as a pillow.",
      "characters": ["sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "Mara tries to wake him for the gate password.",
      "visual_description": "The cartographer shakes the slumbering official by the shoulder; his ledger flops open showing nonsense stamps while the lamp glares disapprovingly.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "Armored patrols clatter past in the rubble street.",
      "visual_description": "From behind a toppled statue, the team watches plated boots and pikes march by; only silhouettes and shadows show on the cracked wall.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "Glass Diver slips through a tall stained window.",
      "visual_description": "A coated figure dives headfirst into a vertical pane of colored glass as if it were water, ripples spreading outward into a chapel beyond.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "Inside, the oracle lamp reveals a magic door.",
      "visual_description": "A heavy door etched with shifting runes glows where the lamp's single eye points; carved faces along its frame seem to whisper.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "Tin Fox picks the door's rune-lock with its tail key.",
      "visual_description": "The clockwork fox stands on hind legs, key-wind tail inserted into a glowing keyhole; sparks of blue light spiral around its metal ears.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "They find the captive chained in a frosted hall.",
      "visual_description": "A figure shackled to a throne of cracked ice in a long mirrored hall; Mara rushes forward, compass spinning wildly out of control.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 13,
      "caption": "Rumors of a dragon shake dust from the rafters.",
      "visual_description": "A distant roar trembles through the hall; chandeliers swing and stone dust falls as the companions look up wide-eyed at vibrating beams.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 14,
      "caption": "The sleeping tax collector stumbles in, still half-asleep.",
      "visual_description": "The official wanders through the wrong doorway clutching his ledger, stamped papers fluttering, eyes barely open as plaster rains around him.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 15,
      "caption": "Glass Diver pulls everyone into a tall standing mirror.",
      "visual_description": "Hands clasped, the team plunges into a silver mirror that ripples like a pond; reflections of broken banners blur around them.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 16,
      "caption": "They emerge on the river bridge under torchlight.",
      "visual_description": "Wet footprints lead from a puddle onto an arched stone bridge; torches sputter and a moonlit river churns far below.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "The oracle lamp shouts to run as the bridge cracks.",
      "visual_description": "The lamp's flame-eye flares huge and white; stones split underfoot and Mara hauls the snoring official forward by his collar.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far shore, Mara marks the city as rescued.",
      "visual_description": "Dawn light over distant ruined spires; the cartographer stamps an inked X on her map while the tin fox watches and the lamp's eye dims contentedly.",
      "characters": ["mara_the_cartographer", "tin_fox", "oracle_lamp", "glass_diver", "sleeping_tax_collector"]
    }
  ]
}

